const VERSION='dez-voltas-v28';
const ASSETS=['/','/index.html','/style.css','/app.js','/profile.js','/push-settings.js','/push-contract.js','/daily-recovery.js','/recovery-sync.js','/recovery-contract.js','/plan-comparison.js','/active-plan.js','/account-sync.js','/session-client.js','/sync-contract.js','/relational-contract.js','/training-contract.js','/goal-context.js','/weekly-contract.js','/workout-contract.js','/weekly-review.js','/plan.js','/workout-fit.js','/manifest.webmanifest','/icons/icon.svg','/icons/icon-192.png','/icons/icon-512.png','/icons/maskable-512.png','/icons/apple-touch-icon.png'];
self.addEventListener('install',event=>{event.waitUntil((async()=>{const cache=await caches.open(VERSION);for(const path of ASSETS){const r=await fetch(new Request(path,{cache:'reload',credentials:'same-origin'}));if(!r.ok||r.redirected)throw new Error('App shell unavailable');await cache.put(path,r);}await self.skipWaiting();})());});
self.addEventListener('activate',event=>{event.waitUntil((async()=>{for(const key of await caches.keys()){if(key.startsWith('dez-voltas-')&&key!==VERSION)await caches.delete(key);}await self.clients.claim();})());});
self.addEventListener('fetch',event=>{const req=event.request,url=new URL(req.url);if(req.method!=='GET'||url.origin!==self.location.origin)return;if(req.mode==='navigate'&&(url.pathname==='/'||url.pathname==='/index.html')){event.respondWith((async()=>{try{const r=await fetch(req);if(r.ok&&!r.redirected&&r.headers.get('content-type')?.includes('text/html')){const cache=await caches.open(VERSION);await cache.put('/',r.clone());}return r;}catch{const cache=await caches.open(VERSION);return (await cache.match('/'))||Response.error();}})());return;}if(ASSETS.includes(url.pathname)){event.respondWith((async()=>{const cache=await caches.open(VERSION);const cached=await cache.match(url.pathname);return cached||fetch(req);})());}});

self.addEventListener('push',event=>{event.waitUntil((async()=>{let data={};try{data=event.data?.json()||{};}catch{}const kind=['training','diary','test'].includes(data.type)?data.type:'test';const body=kind==='training'?'Confira o treino programado para hoje antes de começar.':kind==='diary'?'Como foi seu dia? Registre seu check-in, mesmo sem corrida.':'Os lembretes do Dez Voltas estão funcionando neste aparelho.';await self.registration.showNotification('Dez Voltas',{body,icon:'/icons/icon-192.png',badge:'/icons/icon-192.png',tag:'dez-voltas-'+kind,renotify:false,data:{url:'/#hoje'}});})());});
self.addEventListener('notificationclick',event=>{event.notification.close();event.waitUntil((async()=>{const target=event.notification.data?.url==='/#perfil'?'/#perfil':'/#hoje';const url=new URL(target,self.location.origin).href;const windows=await self.clients.matchAll({type:'window',includeUncontrolled:true});const client=windows.find(c=>new URL(c.url).origin===self.location.origin);if(client){await client.navigate(url);await client.focus();}else await self.clients.openWindow(url);})());});
self.addEventListener('pushsubscriptionchange',event=>{event.waitUntil(self.registration.showNotification('Dez Voltas',{body:'Abra Minha conta para reativar os lembretes deste aparelho.',icon:'/icons/icon-192.png',tag:'dez-voltas-renew',data:{url:'/#perfil'}}));});
